+ r_rsh0   = rsh_nwell
+ r_dw     = 2.22E-7
+ r_dl     = 1.02E-8
+ r_vc1    = 0
+ r_vc2    = 0
+ r_tc1    = 2.285E-3
+ r_tc2    = 9.78E-6
